def calculate_a(N):
    a = {1: 1, 2: 1}
    for n in range(3, N + 1):
        # a_n = a_{a_{n-1}} + a_{n - a_{n-1}}
        try:
            a_n_minus_1 = a[n-1]
            term1 = a[a_n_minus_1]
            term2 = a[n - a_n_minus_1]
            a[n] = term1 + term2
        except KeyError as e:
            print(f"Error: Index {e} required for n={n}, sequence calculation failed.")
            return None
    return a

# Test initial terms
N_test = 16
sequence = calculate_a(N_test)
print("Initial sequence (up to N=16):")
print(sequence)

def calculate_a(N):
    a = [0] * (N + 1)
    a[1] = 1
    a[2] = 1
    for n in range(3, N + 1):
        # a_n = a_{a_{n-1}} + a_{n - a_{n-1}}
        try:
            i = a[n-1]
            j = n - a[n-1]
            if i <= N and j <= N:
                a[n] = a[i] + a[j]
            else:
                # This should not happen if N is large enough and the sequence terms grow slower than N
                # But as a safeguard, we stop or handle error
                a[n] = -1 # Indicator of failure
        except IndexError:
            a[n] = -2 # Indicator of index out of bounds
    return a

# Calculate up to n=64 to see patterns for 31 and beyond
N_max = 64
A = calculate_a(N_max)
print(f"Sequence up to n=15: {A[1:16]}")

# Test the specific points 2^k - 1
power_of_2_minus_1 = []
for k in range(2, 7): # Check k=2 to k=6 (n=3 to n=63)
    n = 2**k - 1
    if n <= N_max:
        power_of_2_minus_1.append((n, A[n]))

print(f"\nValues for n = 2^k - 1:")
for n, val in power_of_2_minus_1:
    print(f"a_{n} = {val}")

# Test monotonicity for a larger range (e.g., n=1 to 40)
print("\nChecking monotonicity (is a_n >= a_{n-1} for n=3 to 40):")
is_monotonic = True
for n in range(3, 41):
    if A[n] < A[n-1]:
        print(f"Monotonicity failed at n={n}: a_{n}={A[n]} < a_{n-1}={A[n-1]}")
        is_monotonic = False
        break
if is_monotonic:
    print("Sequence appears monotonic up to n=40.")
